DROP TABLE IF EXISTS company_info;

CREATE TABLE `company_info` (
  `com_id` int(11) NOT NULL AUTO_INCREMENT,
  `com_name` varchar(50) NOT NULL,
  `com_phone` varchar(20) NOT NULL,
  `com_tel` varchar(20) NOT NULL,
  `com_email` text NOT NULL,
  `com_logo` text NOT NULL,
  `com_address` text NOT NULL,
  `close` int(11) NOT NULL,
  `status` int(11) NOT NULL,
  PRIMARY KEY (`com_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS dialysis_item;

CREATE TABLE `dialysis_item` (
  `di_id` int(11) NOT NULL AUTO_INCREMENT,
  `item_name` text NOT NULL,
  `stock` int(11) NOT NULL,
  `last_update` date NOT NULL,
  PRIMARY KEY (`di_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

