DROP TABLE IF EXISTS indoor_room;

CREATE TABLE `indoor_room` (
  `ir_id` int(11) NOT NULL AUTO_INCREMENT,
  `room_no` text NOT NULL,
  `status` text NOT NULL,
  PRIMARY KEY (`ir_id`)
) ENGINE=InnoDB AUTO_INCREMENT=118 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS payments;

CREATE TABLE `payments` (
  `p_id` int(11) NOT NULL AUTO_INCREMENT,
  `e_id` int(11) NOT NULL,
  `p_date` date NOT NULL,
  `p_purpose` varchar(25) NOT NULL,
  `total_salary` int(11) NOT NULL,
  `p_debit` int(11) NOT NULL,
  `p_credit` int(11) NOT NULL,
  `bonus` int(11) DEFAULT NULL,
  `absents` int(11) DEFAULT NULL,
  `deductions` int(11) DEFAULT NULL,
  `close` int(2) NOT NULL,
  `status` int(2) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`p_id`)
) ENGINE=InnoDB AUTO_INCREMENT=120 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_assets;

CREATE TABLE `ssh_assets` (
  `A_ID` int(11) NOT NULL AUTO_INCREMENT,
  `A_Name` varchar(100) NOT NULL,
  PRIMARY KEY (`A_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_assets_types;

CREATE TABLE `ssh_assets_types` (
  `at_id` int(11) NOT NULL AUTO_INCREMENT,
  `A_id` int(11) NOT NULL,
  `name` text NOT NULL,
  `value` int(11) NOT NULL,
  PRIMARY KEY (`at_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_cases_indoor;

CREATE TABLE `ssh_cases_indoor` (
  `S_ID` int(11) NOT NULL AUTO_INCREMENT,
  `Title` varchar(40) NOT NULL,
  `Charges` int(11) NOT NULL,
  `type` int(11) NOT NULL,
  `close` int(11) NOT NULL,
  PRIMARY KEY (`S_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=432 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_docsetting_indoor;

CREATE TABLE `ssh_docsetting_indoor` (
  `ds_id` int(11) NOT NULL AUTO_INCREMENT,
  `S_ID` int(11) NOT NULL,
  `D_ID` int(11) NOT NULL,
  `doc_charges` int(11) NOT NULL,
  `close` int(11) NOT NULL,
  PRIMARY KEY (`ds_id`)
) ENGINE=InnoDB AUTO_INCREMENT=507 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_dr_payment;

CREATE TABLE `ssh_dr_payment` (
  `Payment` int(11) NOT NULL,
  `Date` date NOT NULL,
  `Status` varchar(10) NOT NULL,
  `D_ID` int(11) NOT NULL,
  `notification` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_dr_payment_indoor;

CREATE TABLE `ssh_dr_payment_indoor` (
  `pay_id` int(11) NOT NULL AUTO_INCREMENT,
  `payment` int(11) NOT NULL,
  `D_ID` int(11) NOT NULL,
  `Date` date NOT NULL,
  `checkno` text NOT NULL,
  `type` int(11) NOT NULL,
  PRIMARY KEY (`pay_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4491 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_dr_reg;

CREATE TABLE `ssh_dr_reg` (
  `CNIC` varchar(13) NOT NULL,
  `Name` varchar(40) NOT NULL,
  `DOB` date NOT NULL,
  `Address` varchar(200) NOT NULL,
  `Phone` varchar(13) NOT NULL,
  `Gender` varchar(6) NOT NULL,
  `Picture` longblob NOT NULL,
  `DOJ` date NOT NULL,
  `DOR` date DEFAULT NULL,
  `TOD` time NOT NULL,
  `TOD_TO` time NOT NULL,
  `duty_days` text NOT NULL,
  `Qualification` varchar(300) NOT NULL,
  `Expertise` varchar(100) NOT NULL,
  `status` int(11) NOT NULL,
  `Wages` int(11) NOT NULL,
  `Shares` int(11) NOT NULL,
  `Indoor_Shares` int(11) NOT NULL,
  `D_ID` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`D_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_expenses;

CREATE TABLE `ssh_expenses` (
  `Voucher` int(11) NOT NULL AUTO_INCREMENT,
  `services` int(11) NOT NULL,
  `Title` varchar(300) NOT NULL,
  `quantity` int(11) NOT NULL,
  `Amount` int(11) NOT NULL,
  `paid` int(11) NOT NULL,
  `payment_date` date NOT NULL,
  `Date` date NOT NULL,
  `user_id` int(11) NOT NULL,
  PRIMARY KEY (`Voucher`)
) ENGINE=InnoDB AUTO_INCREMENT=3294 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_general_income;

CREATE TABLE `ssh_general_income` (
  `i_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `title` text NOT NULL,
  `income` int(11) NOT NULL,
  `created_at` date NOT NULL,
  PRIMARY KEY (`i_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_p_dialysis;

CREATE TABLE `ssh_p_dialysis` (
  `pd_id` int(11) NOT NULL AUTO_INCREMENT,
  `visitor_id` int(11) NOT NULL,
  `P_ID` int(11) NOT NULL,
  `injection` int(11) NOT NULL DEFAULT 2,
  `Paid` int(11) NOT NULL,
  `admission_type` int(11) NOT NULL,
  `date` date NOT NULL,
  `file_status` int(11) NOT NULL,
  `file_date` date NOT NULL,
  `receive_date` date NOT NULL,
  `payment_details` text NOT NULL,
  PRIMARY KEY (`pd_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1655 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS ssh_p_dpr;

CREATE TABLE `ssh_p_dpr` (
  `MRN` int(11) NOT NULL AUTO_INCREMENT,
